let c = { (a: Int) -> String in
    a == 0 ? "no more bottles" : a == 1 ? "1 bottle" : "\(a) bottles"
}

let p = { (s: Int) in
    let a = c(s)
    let n = c(s - 1)

    let f = "\(a.prefix(1).uppercased())\(a.dropFirst()) of beer on the wall, \(a) of beer."

    print(f)
    print(s > 0 ? "Take one down and pass it around, \(n) of beer on the wall." : "Go to the store and buy some more, 99 bottles of beer on the wall.")
}

for b in (0...99).reversed() {
    p(b)
    if b > 0 {
        print()
    }
}

func bottleCountText(_ count: Int) -> String {
    switch count {
    case 0:
        return "no more bottles"
    case 1:
        return "1 bottle"
    default:
        return "\(count) bottles"
    }
}

func printVerse(startingBottles: Int) {
    let currentBottles = bottleCountText(startingBottles)
    let nextBottles = bottleCountText(startingBottles - 1)

    let firstLine = "\(currentBottles.prefix(1).uppercased())\(currentBottles.dropFirst()) of beer on the wall, \(currentBottles) of beer."

    if startingBottles > 0 {
        print(firstLine)
        print("Take one down and pass it around, \(nextBottles) of beer on the wall.")
    } else {
        print(firstLine)
        print("Go to the store and buy some more, 99 bottles of beer on the wall.")
    }
}

for bottleCount in (0...99).reversed() {
    printVerse(startingBottles: bottleCount)
    if bottleCount > 0 {
        print()
    }
}

